class Solution:
    def findLeaves(self, root: 'TreeNode | None') -> list[list[int]]:
        groups = []

        def height(node) -> int:
            if not node:
                return 0
            h = 1 + max(height(node.left), height(node.right))   # post-order: children first
            if h > len(groups):
                groups.append([])               # first node of this height opens its round
            groups[h - 1].append(node.val)      # removed in round h
            return h

        height(root)                            # each node visited once
        return groups
